package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mockStatic;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.IntStream;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.csf.PersistentCsfPageCodec;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.mockito.MockedStatic;

/** A physical batch may reuse detached base pages only within its synchronous mutation scope. */
class LmdbPersistentAdjacencyBatchWorkTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@CsvSource({ "1024,1,2", "1024,8,16", "4096,1,8" })
	void alignedWritesDecodeEachTouchedBasePageOnce(int seedCount, int predicates, int maximumPages) throws Exception {
		LmdbStoreConfig config = config();
		long[][] input = input(seedCount, predicates);
		try (TripleStore store = seeded(config, seedCount, predicates)) {
			store.startTransaction();
			AtomicInteger decodes = new AtomicInteger();
			List<Integer> added = new ArrayList<>();
			try (MockedStatic<PersistentCsfPageCodec> ignored = mockStatic(PersistentCsfPageCodec.class, invocation -> {
				if (invocation.getMethod().getName().equals("decode")) {
					decodes.incrementAndGet();
				}
				return invocation.callRealMethod();
			})) {
				store.storeTriplesAligned(input[0], input[1], input[2], input[3], input[0].length, true, true,
						added::add);
			}
			assertThat(added).containsExactlyElementsOf(IntStream.range(0, 64).boxed().toList());
			assertLive(store, input, seedCount + 64);
			store.commit();
			assertThat(decodes.get()).as("bounded batch cache follows physical pages across both directions")
					.isLessThanOrEqualTo(maximumPages);
		}
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.getTxnManager().doWith((stack, txn) -> {
				assertLive(LmdbPersistentAdjacency.openExisting(txn), txn, input, seedCount + 64);
				return null;
			});
		}
	}

	@Test
	void batchStateDoesNotSurviveCompactionRollbackOrCallbackPublication() throws Exception {
		long[][] input = input(1024, 1);
		try (TripleStore store = seeded(config(), 1024, 1)) {
			store.startTransaction();
			store.storeTriplesAligned(input[0], input[1], input[2], input[3], input[0].length, true, true, index -> {
				try {
					// Caller callbacks run after the physical batch has published every count and closed its workspace.
					assertThat(LmdbPersistentAdjacency.openExisting(store.writeTxn).count(store.writeTxn, true))
							.isEqualTo(1088);
				} catch (IOException failure) {
					throw new AssertionError(failure);
				}
			});
			LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
			assertLive(store, input, 1088);
			store.rollback();

			store.startTransaction();
			List<Integer> added = new ArrayList<>();
			store.storeTriplesAligned(input[0], input[1], input[2], input[3], input[0].length, true, true, added::add);
			assertThat(added).hasSize(64);
			LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
			added.clear();
			store.storeTriplesAligned(input[0], input[1], input[2], input[3], input[0].length, true, true, added::add);
			assertThat(added).isEmpty();
			assertLive(store, input, 1088);
			store.commit();
		}
	}

	private TripleStore seeded(LmdbStoreConfig config, int count, int predicates) throws IOException {
		TripleStore store = new TripleStore(directory.toFile(), config, null);
		try {
			store.startTransaction();
			for (int i = 0; i < count; i++) {
				store.storeTriple(1000L + i, 20L + i % predicates, 5000L + 2L * i, 0, true);
			}
			store.commit();
			return store;
		} catch (IOException | RuntimeException | Error failure) {
			store.close();
			throw failure;
		}
	}

	private static long[][] input(int seedCount, int predicates) {
		long[][] input = new long[4][80];
		for (int i = 0; i < 64; i++) {
			int seed = i < 4 && seedCount > 1024 ? 1023 + i : i * 61 % seedCount;
			input[0][i] = 1000L + seed;
			input[1][i] = 20L + seed % predicates;
			input[2][i] = 5001L + 2L * seed;
		}
		for (long[] column : input) {
			System.arraycopy(column, 0, column, 64, 16);
		}
		return input;
	}

	private static void assertLive(TripleStore store, long[][] input, long expected) throws IOException {
		assertLive(LmdbPersistentAdjacency.openExisting(store.writeTxn), store.writeTxn, input, expected);
	}

	private static void assertLive(LmdbPersistentAdjacency adjacency, long txn, long[][] input, long expected)
			throws IOException {
		assertThat(adjacency.count(txn, true)).isEqualTo(expected);
		for (int i = 0; i < 64; i++) {
			for (boolean incoming : new boolean[] { false, true }) {
				assertThat(adjacency.contains(txn, input[0][i], input[1][i], input[2][i], input[3][i], true, incoming))
						.isTrue();
			}
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setAutoGrow(false)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setTripleDBSize(64L << 20);
	}
}
